# slickrails: checks for this repo's git hooks (generated by install.sh).
# Empty string = check skipped. Commands run in the repo root.
CHECK_TYPECHECK="sh scripts/lint.sh"
CHECK_TEST="sh tests/run.sh"
CHECK_LINT_STAGED=""
# Review strictness for all AI reviews: quiet | chill | assertive.
REVIEW_PROFILE="chill"
CHECK_PREPUSH_REVIEW="1"
REVIEW_CLI="auto"
REVIEW_TIMEOUT="300"
